export const updateAdminSettingsBodyAnnouncementMax = 1000;

export const updateAdminSettingsBodyTelegramUsernameRegExp = new RegExp('^[A-Za-z0-9_]{5,32}$');
export const updateAdminSettingsBodyReferralCommissionPercentMin = 0;
export const updateAdminSettingsBodyReferralCommissionPercentMax = 100;

export const updateAdminSettingsBodyBkashNumberMax = 30;

export const updateAdminSettingsBodyNagadNumberMax = 30;

export const updateAdminSettingsBodyPaymentInstructionsMax = 2000;

export const updateAdminSettingsBodyMinimumDepositMin = 0;

export const updateAdminSettingsBodyMinimumWithdrawalMin = 0;



export const UpdateAdminSettingsBody = zod.object({
  "websiteName": zod.string().min(1).max(updateAdminSettingsBodyWebsiteNameMax).optional(),
  "logoUrl": zod.string().url().nullish(),
  "primaryColor": zod.string().regex(updateAdminSettingsBodyPrimaryColorRegExp).optional(),
  "accentColor": zod.string().regex(updateAdminSettingsBodyAccentColorRegExp).optional(),
  "homepageTitle": zod.string().max(updateAdminSettingsBodyHomepageTitleMax).optional(),
  "homepageDescription": zod.string().max(updateAdminSettingsBodyHomepageDescriptionMax).optional(),
  "bannerImageUrl": zod.string().url().nullish(),
  "announcement": zod.string().max(updateAdminSettingsBodyAnnouncementMax).nullish(),
  "telegramUsername": zod.string().regex(updateAdminSettingsBodyTelegramUsernameRegExp).optional(),
  "referralCommissionPercent": zod.number().min(updateAdminSettingsBodyReferralCommissionPercentMin).max(updateAdminSettingsBodyReferralCommissionPercentMax).optional(),
  "bkashNumber": zod.string().max(updateAdminSettingsBodyBkashNumberMax).optional(),
  "nagadNumber": zod.string().max(updateAdminSettingsBodyNagadNumberMax).optional(),
  "paymentInstructions": zod.string().max(updateAdminSettingsBodyPaymentInstructionsMax).optional(),
  "minimumDeposit": zod.number().min(updateAdminSettingsBodyMinimumDepositMin).optional(),
  "minimumWithdrawal": zod.number().min(updateAdminSettingsBodyMinimumWithdrawalMin).optional()
})

export const UpdateAdminSettingsResponse = zod.object({
  "websiteName": zod.string(),
  "logoUrl": zod.string().nullable(),
  "primaryColor": zod.string(),
  "accentColor": zod.string(),
  "homepageTitle": zod.string(),
  "homepageDescription": zod.string(),
  "bannerImageUrl": zod.string().nullable(),
  "announcement": zod.string().nullable(),
  "telegramUsername": zod.string(),
  "referralCommissionPercent": zod.number()
}).and(zod.object({
  "bkashNumber": zod.string(),
  "nagadNumber": zod.string(),
  "paymentInstructions": zod.string(),
  "minimumDeposit": zod.number(),
  "minimumWithdrawal": zod.number()
}))


/**
 * @summary List administrator actions
 */
export const ListAdminAuditLogResponseItem = zod.object({
  "id": zod.string().uuid(),
  "adminEmail": zod.string().email(),
  "action": zod.string(),
  "targetType": zod.string(),
  "targetId": zod.string().nullable(),
  "details": zod.string(),
  "createdAt": zod.coerce.date()
})
export const ListAdminAuditLogResponse = zod.array(ListAdminAuditLogResponseItem)


